CREATE TABLE IF NOT EXISTS pages (slug TEXT PRIMARY KEY, menu_label TEXT NOT NULL, eyebrow TEXT NOT NULL, title TEXT NOT NULL, introduction TEXT NOT NULL, body TEXT NOT NULL, position INTEGER NOT NULL, published INTEGER NOT NULL DEFAULT 1);
INSERT OR IGNORE INTO pages VALUES ('cours','Cours','École d’équitation','Grandir à cheval.','Des cours adaptés à chaque âge et à chaque niveau.','Du premier contact avec le poney au perfectionnement, nous vous accompagnons pas à pas.',10,1),('stages','Stages','Vacances & passion','Des journées qui comptent.','Des stages pour progresser et vivre la vie du centre.','Des activités variées, du temps à cheval et une ambiance conviviale.',20,1),('balades','Balades','En pleine nature','Prendre le temps.','Découvrez les environs de Brienne-le-Château au rythme du cheval.','Nos promenades sont organisées selon le niveau et sur rendez-vous.',30,1),('demi-pensions','Demi-pensions','Créer un lien','Votre poney, autrement.','Développez une relation privilégiée avec un poney.','Une formule idéale à partir du Galop 3 pour monter davantage.',40,1),('pensions','Pensions','Écurie propriétaire','Le bien-être avant tout.','Un cadre attentif pour votre cheval.','Des solutions de pension adaptées à vos besoins.',50,1),('prestations','Prestations','Accompagnement','Aller plus loin ensemble.','Valorisation, coaching et suivi personnalisé.','Du débourrage à la compétition, construisons votre projet.',60,1),('challenge-hivernal','Challenge','Au fil de l’hiver','Le goût du défi.','Un rendez-vous convivial pour se dépasser.','Retrouvez les dates et informations pratiques du Challenge Hivernal.',70,1),('contact','Contact','Nous rencontrer','Parlons de votre projet.','Une question ou envie de découvrir le centre ?','23 ter rue Dominique Larrey, 10500 Brienne-le-Château\n06 52 54 68 78\ncentreequestredugrandrang@gmail.com',80,1);
